mapper.sql:
FROM file_ref fr JOIN file_info f ON f.id = fr.file_id AND f.deleted = 0 LEFT JOIN submission s ON fr.biz_type = 'SUBMISSION' AND s.id = fr.biz_id LEFT JOIN task t ON t.id = s.task_id AND t.deleted = 0 LEFT JOIN adjustment a ON fr.biz_type = 'ADJUSTMENT' AND a.id = fr.biz_id LEFT JOIN milestone m ON fr.biz_type = 'MILESTONE' AND m.id = fr.biz_id JOIN indicator i ON i.id = CASE fr.biz_type WHEN 'INDICATOR' THEN fr.biz_id WHEN 'SUBMISSION' THEN s.indicator_id WHEN 'ADJUSTMENT' THEN a.indicator_id WHEN 'MILESTONE' THEN m.indicator_id ELSE NULL END AND i.deleted = 0 JOIN indicator ti ON ti.id = COALESCE(i.parent_id, i.id) AND ti.level = 'A' AND ti.deleted = 0 LEFT JOIN direction d ON d.id = ti.direction_id AND d.deleted = 0 LEFT JOIN sys_user su ON su.id = f.uploaded_by LEFT JOIN org_unit ou ON ou.id = COALESCE(s.unit_id, su.unit_id) AND ou.deleted = 0 WHERE fr.biz_type IN ('INDICATOR', 'SUBMISSION', 'ADJUSTMENT', 'MILESTONE') AND (fr.biz_type != 'SUBMISSION' OR s.status = 'APPROVED')
AND ti.plan_id = #{query.planId}
AND ti.id = #{query.indicatorId}
AND ( (fr.biz_type = 'SUBMISSION' AND s.unit_id = #{query.unitId}) OR (fr.biz_type != 'SUBMISSION' AND EXISTS ( SELECT 1 FROM user_unit filter_uu JOIN task filter_task ON filter_task.unit_id = filter_uu.unit_id AND filter_task.top_indicator_id = ti.id AND filter_task.deleted = 0 WHERE filter_uu.user_id = f.uploaded_by AND filter_uu.unit_id = #{query.unitId} )) )
AND fr.biz_type = 'SUBMISSION'
AND s.task_id = #{query.taskId}
AND s.year = #{query.year}
AND f.category = #{query.category}
AND (LOWER(f.file_name) LIKE CONCAT('%', #{query.keyword}, '%') OR LOWER(ti.code) LIKE CONCAT('%', #{query.keyword}, '%') OR LOWER(ti.name) LIKE CONCAT('%', #{query.keyword}, '%'))
AND f.id IN
#{fileId}
AND (
ti.owner_id = #{query.ownerScope}
OR
( (fr.biz_type = 'SUBMISSION' AND s.unit_id IN
#{scopeUnitId}
AND EXISTS ( SELECT 1 FROM task scoped_task WHERE scoped_task.top_indicator_id = ti.id AND scoped_task.unit_id = s.unit_id AND scoped_task.deleted = 0 )) OR (fr.biz_type != 'SUBMISSION' AND EXISTS ( SELECT 1 FROM user_unit scoped_uu JOIN task scoped_task ON scoped_task.unit_id = scoped_uu.unit_id AND scoped_task.top_indicator_id = ti.id AND scoped_task.deleted = 0 WHERE scoped_uu.user_id = f.uploaded_by AND scoped_uu.unit_id IN
#{scopeUnitId}
)) )
)

mapper.select:
SELECT f.id AS file_id, f.file_name, f.size, f.mime_type, f.category, fr.biz_type, f.uploaded_at, s.year AS submission_year, s.task_id AS task_id, t.code AS task_code, ti.id AS indicator_id, ti.code AS indicator_code, ti.name AS indicator_name, d.name AS direction_name, s.reviewed_at, ou.id AS unit_id, ou.code AS unit_code, ou.name AS unit_name, su.id AS uploader_id, su.name AS uploader_name
ORDER BY f.uploaded_at DESC, f.id DESC, fr.id ASC
LIMIT #{query.limit} OFFSET #{query.offset}
